"""rad0034 (VTP39): opt-in concurrent long-prefill admission policy.

Source-pinned to Radiance v1.17.0; zero takes the pre-existing planning path.
"""
from __future__ import annotations

import re
from bigcherry.patcher import Edit, FilePatch


def _edit(id: str, before: str, after: str, guard: str) -> Edit:
    return Edit(id=id, anchor=re.escape(before), mode="replace", text=after,
                guard=re.escape(guard), expect_matches=1,
                max_span_lines=max(4, before.count("\n") + 2),
                rationale="VTP39: optional concurrent long-prefill admission policy")


