        _edit("scheduler-count", "    Program*      prog_ = nullptr;", "    /* BC_VTP39_PREFILL_COUNT: unfinished prompts among RUNNING only. */\n    int64_t prefilling_running() const;\n    Program*      prog_ = nullptr;", "BC_VTP39_PREFILL_COUNT"),
